function makeBrowser(dom) {
  const wrap = (el) => ({ getText: async () => el.text, isDisplayed: async () => el.displayed });
  return {
    async $(sel) {
      const el = dom.find(e => e.sel === sel);
      if (el) return wrap(el);
      return {
        isDisplayed: async () => false,
        getText: async () => { throw new Error(`element ("${sel}") still not existing`); },
      };
    },
    async $$(sel) {
      return dom.filter(e => e.sel === sel).map(wrap);
    },
  };
}

coding.prompt:
Write `addCommand(target, name, fn)` that adds a method called `name` to `target`. When called, the method must run `fn` with `this` bound to `target` and pass through all arguments, returning `fn`'s result (which may be a Promise). Throw `Error('command exists: <name>')` if `target` already has a property with that name.

```js
const browser = { url: '/' };
addCommand(browser, 'where', function () { return this.url; });
browser.where(); // '/'
```

coding.solution:
function addCommand(target, name, fn) {
  if (name in target) throw new Error(`command exists: ${name}`);
  target[name] = function (...args) {
    return fn.apply(target, args);
  };
}
